Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Sat Jun 11 22:44:47 2022 +0200

    Fix bitreader bug, leaving bitreader in undefined state

    When a call to read_callback failed in bitreader_read_from_client_
    it left the bitreader buffer in a state where the last word was swapped
    for endianness. While this wasn't ever a problem, recently code was
    merged that rewound the bitreader in case a bogus frame was found.
    If this happened, the bitreader buffer would be used in the state
    where the last word in the buffer was still swapped. This commit
    restores the last word of the buffer in case the call to the
    read callback fails

diff --git a/src/libFLAC/bitreader.c b/src/libFLAC/bitreader.c
index 4796f337..df1182ba 100644
--- a/src/libFLAC/bitreader.c
+++ b/src/libFLAC/bitreader.c
@@ -158,6 +158,10 @@ static FLAC__bool bitreader_read_from_client_(FLAC__BitReader *br)
        uint32_t start, end;
        size_t bytes;
        FLAC__byte *target;
+#if WORDS_BIGENDIAN
+#else
+       brword preswap_backup;
+#endif

        /* invalidate last seen framesync */
        br->last_seen_framesync = -1;
@@ -192,6 +196,7 @@ static FLAC__bool bitreader_read_from_client_(FLAC__BitReader *br)
         */
 #if WORDS_BIGENDIAN
 #else
+       preswap_backup = br->buffer[br->words];
        if(br->bytes)
                br->buffer[br->words] = SWAP_BE_WORD_TO_HOST(br->buffer[br->words]);
 #endif
@@ -204,8 +209,16 @@ static FLAC__bool bitreader_read_from_client_(FLAC__BitReader *br)
         */

        /* read in the data; note that the callback may return a smaller number of bytes */
-       if(!br->read_callback(target, &bytes, br->client_data))
+       if(!br->read_callback(target, &bytes, br->client_data)){
+               /* Despite the read callback failing, the data in the target
+                * might be used later, when the buffer is rewound. Therefore
+                * we revert the swap that was just done */
+#if WORDS_BIGENDIAN
+#else
+               br->buffer[br->words] = preswap_backup;
+#endif
                return false;
+       }

